{
  "version": 3,
  "sources": ["challan-detail.component.ts"],
  "sourcesContent": ["\n    .challan-detail-container {\n      max-width: 1100px;\n      margin: 0 auto;\n    }\n\n    .back-link {\n      margin-bottom: 20px;\n    }\n\n    .back-link a {\n      color: #0066cc;\n      text-decoration: none;\n      font-size: 14px;\n    }\n\n    .loading {\n      text-align: center;\n      padding: 60px 20px;\n    }\n\n    .spinner {\n      width: 40px;\n      height: 40px;\n      border: 3px solid #e5e7eb;\n      border-top-color: #0066cc;\n      border-radius: 50%;\n      margin: 0 auto 16px;\n      animation: spin 1s linear infinite;\n    }\n\n    @keyframes spin {\n      to { transform: rotate(360deg); }\n    }\n\n    .challan-header-card {\n      background: #fff;\n      border-radius: 12px;\n      padding: 24px;\n      margin-bottom: 24px;\n      box-shadow: 0 2px 8px rgba(0,0,0,0.08);\n    }\n\n    .header-top {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n    }\n\n    .challan-title {\n      display: flex;\n      align-items: center;\n      gap: 16px;\n    }\n\n    .challan-title h1 {\n      font-size: 24px;\n      font-weight: 700;\n      margin: 0;\n      color: #1a1a1a;\n    }\n\n    .status-badge {\n      padding: 6px 14px;\n      border-radius: 20px;\n      font-size: 13px;\n      font-weight: 500;\n    }\n\n    .status-pending { background: #fef3c7; color: #92400e; }\n    .status-paid { background: #d1fae5; color: #065f46; }\n    .status-disputed { background: #fee2e2; color: #991b1b; }\n\n    .fine-amount {\n      text-align: right;\n    }\n\n    .fine-amount .label {\n      display: block;\n      font-size: 13px;\n      color: #666;\n      margin-bottom: 4px;\n    }\n\n    .fine-amount strong {\n      font-size: 28px;\n      color: #dc3545;\n    }\n\n    .content-grid {\n      display: grid;\n      grid-template-columns: 1fr 350px;\n      gap: 24px;\n    }\n\n    @media (max-width: 900px) {\n      .content-grid {\n        grid-template-columns: 1fr;\n      }\n    }\n\n    .card {\n      background: #fff;\n      border-radius: 12px;\n      padding: 24px;\n      box-shadow: 0 2px 8px rgba(0,0,0,0.08);\n      margin-bottom: 24px;\n    }\n\n    .card h2, .card h3 {\n      font-size: 18px;\n      font-weight: 600;\n      color: #1a1a1a;\n      margin: 0 0 20px;\n    }\n\n    .violation-info {\n      margin-bottom: 24px;\n      padding-bottom: 20px;\n      border-bottom: 1px solid #e5e7eb;\n    }\n\n    .violation-info h3 {\n      font-size: 16px;\n      color: #dc3545;\n      margin-bottom: 8px;\n    }\n\n    .violation-info p {\n      color: #666;\n      margin: 0;\n      line-height: 1.6;\n    }\n\n    .details-grid {\n      display: grid;\n      grid-template-columns: repeat(2, 1fr);\n      gap: 20px;\n    }\n\n    .detail-item {\n      display: flex;\n      flex-direction: column;\n      gap: 4px;\n    }\n\n    .detail-item.full-width {\n      grid-column: 1 / -1;\n    }\n\n    .detail-item .label {\n      font-size: 12px;\n      color: #888;\n      text-transform: uppercase;\n    }\n\n    .detail-item .value {\n      font-size: 15px;\n      color: #1a1a1a;\n    }\n\n    .evidence-image img {\n      width: 100%;\n      border-radius: 8px;\n    }\n\n    .payment-card {\n      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n      color: #fff;\n    }\n\n    .payment-card h3 {\n      color: #fff;\n    }\n\n    .payment-details {\n      margin-bottom: 20px;\n    }\n\n    .payment-row {\n      display: flex;\n      justify-content: space-between;\n      padding: 10px 0;\n      border-bottom: 1px solid rgba(255,255,255,0.2);\n    }\n\n    .payment-row.total {\n      border-bottom: none;\n      padding-top: 16px;\n      margin-top: 8px;\n      border-top: 2px solid rgba(255,255,255,0.3);\n    }\n\n    .payment-row.total strong {\n      font-size: 24px;\n    }\n\n    .btn-primary {\n      padding: 14px 24px;\n      background: #fff;\n      color: #764ba2;\n      border: none;\n      border-radius: 8px;\n      font-weight: 600;\n      font-size: 16px;\n      cursor: pointer;\n    }\n\n    .due-date {\n      text-align: center;\n      margin: 12px 0 0;\n      font-size: 13px;\n      opacity: 0.9;\n    }\n\n    .btn-outline {\n      display: block;\n      padding: 12px 24px;\n      border: 1px solid #e5e7eb;\n      background: #fff;\n      color: #444;\n      border-radius: 6px;\n      text-decoration: none;\n      font-weight: 500;\n      text-align: center;\n      cursor: pointer;\n    }\n\n    .full-width {\n      width: 100%;\n    }\n\n    .help-text {\n      color: #666;\n      font-size: 14px;\n      margin: 0 0 16px;\n    }\n  "],
